// cutColor: filled icon (jaise home pentagon) ke andar jo stroke-only detail hai
// (home ka "smile") use is rang me dikhaya jaata hai — design me ye coral bg hai.
export const NavIcon = ({ name, size = 24, color = "#fff", cutColor }) => {
  const icon = ICONS[name];
  if (!icon) return null;
  const hasFill = icon.paths.some((p) => p.fill && p.fill !== "none");
  return (
    <Svg width={size} height={size} viewBox={icon.vb} fill="none">
      {icon.paths.map((p, i) => {
        const filled = p.fill && p.fill !== "none";
        // Filled shape ke upar wali stroke-only line = cut/smile (cutColor me)
        const strokeColor = !filled && hasFill && cutColor ? cutColor : color;
        return (
          <Path
            key={i}
            d={p.d}
            fill={filled ? color : "none"}
            stroke={p.sw ? strokeColor : undefined}
            strokeWidth={p.sw ? Number(p.sw) : undefined}
            strokeLinecap={p.lc || "round"}
            strokeLinejoin={p.lj || "round"}
          />
        );
      })}
    </Svg>
  );
};
